@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--bg:#090c16;--panel:#101522;--muted:#7b8293;--white:#f5f4f1;--gold:#ffca72;--red:#ff5969;--line:rgba(255,255,255,.085);--display:'Barlow Condensed',Impact,sans-serif;--body:'DM Sans',sans-serif}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 48% -15%,#202338 0,#111421 40%,var(--bg) 78%);color:var(--white);font-family:var(--body);min-height:100vh;padding:0 24px}.game-shell{max-width:1450px;margin:0 auto}.topbar{height:74px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;font:800 21px var(--display);letter-spacing:1.6px;color:#f5f4f1;text-decoration:none}.brand-mark{font-size:23px;color:var(--gold);text-shadow:0 0 15px #f7a94b}.brand-light{font-weight:500;color:#999bab}.season{font-size:10px;letter-spacing:1.8px;font-weight:700;color:#e3e3e9}.season>span:last-child{color:#85899a}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#ff6170;box-shadow:0 0 8px #f34b65;margin-right:8px;vertical-align:1px}.season-divider{color:#494d5d!important;margin:0 10px}.sound-toggle{border:1px solid var(--line);background:#121622;color:#c5c6cf;border-radius:5px;padding:9px 12px;font:700 9px var(--body);letter-spacing:1.2px;cursor:pointer}.sound-toggle span:first-child{color:var(--gold);font-size:14px;margin-right:8px}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 286px;gap:20px;padding:24px 0 18px}.game-column{min-width:0}.arena-frame{position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.13);border-radius:8px;background:#10131f;box-shadow:0 24px 80px #0007;line-height:0}.arena-frame:after{content:'';position:absolute;inset:0;pointer-events:none;border:1px solid #fff1;border-radius:8px;z-index:2}canvas{display:block;width:100%;height:auto;aspect-ratio:5/3;object-fit:contain;background:#111522}.hud{position:absolute;z-index:3;top:17px;left:19px;right:20px;display:flex;align-items:flex-start;justify-content:space-between;line-height:1}.hud-player{display:flex;align-items:center;gap:10px}.avatar{height:34px;width:34px;display:grid;place-items:center;border:1px solid #f6bc6477;border-radius:5px;color:#ffe0a6;background:linear-gradient(140deg,#382c30,#151925);font:800 19px var(--display)}.player-readout{width:152px}.name-line{display:flex;align-items:center;gap:7px;margin-bottom:6px}.player-name{font:800 12px var(--display);letter-spacing:1.6px}.rank-pill{font:700 7px var(--body);letter-spacing:.7px;color:#eac18a;background:#bd824625;border:1px solid #d5a1604c;padding:3px 4px;border-radius:2px}.health-track{height:5px;background:#fff2;border-radius:4px;overflow:hidden}.health-fill{height:100%;width:100%;background:linear-gradient(90deg,#f36b64,#ffb16d);box-shadow:0 0 10px #fa7267;transition:width .25s}.health-number{font:600 10px var(--body);color:#dad7d1}.wave-readout{display:flex;align-items:baseline;gap:7px;margin-top:3px;text-shadow:0 2px 8px #000}.wave-kicker,.enemy-caption{font:700 8px var(--body);letter-spacing:1.4px;color:#c1bfbe}.wave-readout strong{font:800 20px var(--display);color:#fff}.wave-divider{color:#e6b968}.wave-readout>span:nth-last-child(2){font:700 13px var(--display)}.score-readout{text-align:right;text-shadow:0 2px 8px #000}.score-kicker{display:block;color:#cccbd0;font-size:8px;letter-spacing:1px;font-weight:700;margin-bottom:4px}.score-kicker b{color:#ffe0a2;margin-left:4px}.score-readout>strong{font:800 20px var(--display);letter-spacing:1.2px}.combo{display:block;color:#ffc56e;font:800 10px var(--display);letter-spacing:1.3px}.overlay{position:absolute;inset:0;z-index:4;display:flex;justify-content:center;align-items:center;text-align:center;background:linear-gradient(90deg,rgba(8,10,19,.83),rgba(8,10,19,.46) 53%,rgba(8,10,19,.22)),linear-gradient(0deg,#0b0c15a8,transparent 55%);line-height:normal}.overlay-content{margin-top:22px}.eyebrow{display:flex;align-items:center;justify-content:center;gap:11px;color:#e5bd7f;font-size:9px;font-weight:700;letter-spacing:2.6px}.eyebrow span{height:1px;width:21px;background:#dfa856}.overlay h1{font:900 clamp(55px,8vw,95px)/.79 var(--display);letter-spacing:-1px;margin:20px 0 17px;text-shadow:0 4px 30px #0008}.overlay h1 em,.overlay h2 em{font-style:normal;color:var(--gold)}.overlay-content>p{font-size:12px;color:#d0ced0;margin:0 0 22px}.primary-button{background:linear-gradient(110deg,#f4c679,#f4a956);border:0;border-radius:4px;padding:14px 22px;color:#17151a;font:800 11px var(--body);letter-spacing:1.3px;box-shadow:0 5px 22px #efaa4a33;cursor:pointer;transition:transform .15s,filter .15s}.primary-button:hover{transform:translateY(-2px);filter:brightness(1.12)}.primary-button span{font-size:16px;margin-left:14px}.start-meta{display:flex;justify-content:center;gap:22px;margin-top:17px;color:#ded6c9;font:700 8px var(--body);letter-spacing:1.2px}.hidden{display:none!important}.center-notice{position:absolute;z-index:3;left:50%;top:33%;transform:translate(-50%,-50%);font:900 32px var(--display);letter-spacing:4px;color:#ffe0a2;text-shadow:0 0 25px #f88d46;pointer-events:none;opacity:0;transition:opacity .2s}.center-notice.show{opacity:1}.pause-button{position:absolute;z-index:5;right:17px;bottom:15px;width:30px;height:28px;background:#090d18aa;border:1px solid #ffffff3b;border-radius:4px;color:white;font-size:11px;cursor:pointer;opacity:.72}.pause-badge{position:absolute;z-index:6;left:50%;top:50%;transform:translate(-50%,-50%);padding:12px 19px;border:1px solid #ffffff55;background:#0b0e19e8;border-radius:4px;font:800 13px var(--body);letter-spacing:2px;box-shadow:0 8px 40px #0009}.pause-badge span{color:var(--gold);margin-right:8px}.end-content{padding:10px}.overlay h2{font:900 clamp(44px,6.6vw,75px)/.84 var(--display);margin:18px 0 14px}.final-score{display:flex;flex-direction:column;gap:4px;margin:15px 0 18px;font:700 9px var(--body);letter-spacing:1.8px;color:#c3bdb3}.final-score strong{font:800 28px var(--display);color:#ffdc9b}.below-arena{display:flex;align-items:center;justify-content:space-between;padding:15px 3px 0}.arena-caption{display:flex;align-items:center;gap:10px}.caption-icon{font-size:21px;color:#f3be71}.arena-caption b,.arena-caption span{display:block}.arena-caption b{font:800 12px var(--display);letter-spacing:1px}.arena-caption div span{font-size:9px;color:#8f93a0;margin-top:3px}.tip{font-size:10px;color:#aeb0bb}.tip-star{color:#f3bd72;font-size:14px;margin-right:6px}.side-panel{display:flex;flex-direction:column;gap:13px}.panel-top{display:flex;align-items:center;justify-content:space-between;color:#999eaa;font:700 9px var(--body);letter-spacing:1.6px}.three-dots{letter-spacing:2px;color:#727785}.weapon-card,.controls-card,.focus-card{background:linear-gradient(145deg,#141a29,#101420);border:1px solid var(--line);border-radius:6px}.weapon-card{position:relative;overflow:hidden;min-height:245px;padding:17px 17px 14px}.weapon-art{position:absolute;inset:31px 0 60px;overflow:hidden;background:radial-gradient(ellipse at 55% 52%,#3b2b363c 0,transparent 65%)}.weapon-glow{position:absolute;width:150px;height:150px;border:1px solid #c17d512b;border-radius:50%;left:50%;top:40%;transform:translate(-50%,-50%);box-shadow:0 0 45px #fca15610,inset 0 0 30px #cf77730c}.weapon-glow:after,.weapon-glow:before{content:'';position:absolute;inset:13px;border:1px solid #d4a36a18;border-radius:50%}.weapon-glow:before{inset:-13px;border-style:dashed}.katana{position:absolute;height:153px;width:8px;left:57%;top:12%;transform:rotate(37deg);border-radius:60% 60% 4px 4px;background:linear-gradient(90deg,#777c86,#f8f2e4 38%,#fff 55%,#a7a3a0 82%,#4a4b55);clip-path:polygon(25% 7%,50% 0,75% 7%,100% 83%,59% 100%,0 83%);filter:drop-shadow(0 0 8px #f3ba7888)}.katana:after{content:'';position:absolute;bottom:-25px;left:1px;width:6px;height:36px;border-radius:5px;background:repeating-linear-gradient(45deg,#28252b 0 3px,#c88e54 3px 5px)}.katana i{position:absolute;bottom:19px;left:-9px;width:25px;height:5px;border-radius:5px;background:linear-gradient(#f4d296,#735442)}.weapon-spark{position:absolute;color:#ffd99c;font-size:15px;left:31%;top:19%;text-shadow:0 0 14px #fcb15b}.weapon-info{position:relative;z-index:1;margin-top:113px}.weapon-type{font-size:7px;font-weight:800;letter-spacing:1.6px;color:#dfb46f}.weapon-info h2{font:700 25px var(--display);letter-spacing:.4px;margin:2px 0 3px}.weapon-info p{margin:0;color:#9da1ad;font-size:9px;line-height:1.45}.weapon-stats{position:absolute;right:16px;bottom:18px;display:flex;flex-direction:column;align-items:flex-end;gap:7px;font-size:7px;font-weight:700;letter-spacing:.7px;color:#8f94a2}.weapon-stats b{font-size:9px;color:#e9bd7a;margin-right:3px}.stat-bars{display:flex;gap:3px;margin-top:2px}.stat-bars i{display:block;width:11px;height:3px;background:#e8b26a;border-radius:2px}.stat-bars i.dim{background:#393d49}.controls-card{padding:16px 16px 11px}.guide-tag{font-size:7px;color:#ddad68;border:1px solid #ddad6855;padding:4px 5px;border-radius:2px;letter-spacing:.9px}.control-row{display:flex;align-items:center;gap:12px;padding:11px 0;border-bottom:1px solid #ffffff0a}.control-row:last-child{border:0}.control-row>div:last-child b,.control-row>div:last-child span{display:block}.control-row>div:last-child b{font-size:9px;letter-spacing:.8px}.control-row>div:last-child span{margin-top:3px;color:#818694;font-size:8px}.key-group{width:51px;display:flex;flex-direction:column;align-items:center;gap:3px}.key-group>div{display:flex;gap:3px}.key-group kbd,.key-single kbd{font:700 8px var(--body);color:#cfd0d5;background:#1f2533;border:1px solid #343b4b;border-bottom-width:2px;border-radius:3px;min-width:15px;height:14px;display:inline-grid;place-items:center}.key-single{width:51px;text-align:center}.key-single kbd{padding:0 6px;min-width:auto;height:17px;font-size:7px}.focus-card{padding:13px 13px 12px;display:flex;align-items:center;gap:10px}.focus-icon{width:31px;height:31px;border:1px solid #e8ad5a44;border-radius:5px;display:grid;place-items:center;color:#ffc46d;background:#e6a54313;font-size:20px}.focus-card>div:nth-child(2){flex:1}.focus-card>div:nth-child(2)>span{font-size:8px;font-weight:800;letter-spacing:1px;color:#e3c18f}.focus-card p{font-size:8px;line-height:1.5;color:#9398a6;margin:4px 0 0}.focus-card p b{color:#e1c18e}.focus-meter{width:40px;height:4px;background:#303342;border-radius:4px;overflow:hidden}.focus-meter i{display:block;height:100%;width:0;background:#f6bf72;box-shadow:0 0 8px #f6b85d;transition:width .2s}footer{height:40px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#666c7a;font-size:8px;letter-spacing:1.2px;font-weight:700}footer b{color:#c49353;margin-left:4px}footer kbd{font-size:7px;border:1px solid #3c414e;padding:3px 5px;border-radius:3px;color:#b1b2b8}.mobile-controls{display:none}
@media(max-width:900px){body{padding:0 16px}.game-layout{grid-template-columns:minmax(0,1fr) 250px;gap:14px}.weapon-card{min-height:230px}.weapon-info{margin-top:100px}.weapon-art{inset:31px 0 52px}.weapon-stats{right:11px}.tip{max-width:54%;line-height:1.4}}
@media(max-width:680px){body{padding:0 10px 12px}.topbar{height:56px}.brand{font-size:18px}.season{font-size:8px;letter-spacing:1px}.season-divider{margin:0 5px}.sound-toggle{padding:7px 8px;font-size:8px}.game-layout{display:flex;flex-direction:column;padding:12px 0 8px;gap:12px}.arena-frame{border-radius:5px}.hud{top:9px;left:9px;right:9px}.avatar{width:27px;height:27px;font-size:16px}.hud-player{gap:6px}.player-readout{width:95px}.name-line{margin-bottom:4px}.player-name{font-size:10px}.rank-pill{font-size:6px}.health-number{font-size:8px}.wave-readout{gap:4px}.wave-kicker,.enemy-caption{font-size:6px;letter-spacing:.7px}.wave-readout strong{font-size:15px}.wave-readout>span:nth-last-child(2){font-size:10px}.score-kicker{font-size:6px;margin-bottom:2px}.score-readout>strong{font-size:15px}.combo{font-size:8px}.overlay-content{margin-top:14px}.eyebrow{font-size:7px;letter-spacing:1.7px;gap:7px}.eyebrow span{width:14px}.overlay h1{font-size:clamp(43px,12vw,70px);margin:13px 0 11px}.overlay-content>p{font-size:9px;margin-bottom:13px}.primary-button{padding:10px 15px;font-size:9px}.start-meta{font-size:6px;margin-top:10px;gap:13px}.pause-button{right:8px;bottom:8px;width:25px;height:23px}.below-arena{padding-top:10px}.arena-caption b{font-size:10px}.arena-caption div span{font-size:8px}.tip{display:none}.side-panel{display:grid;grid-template-columns:1fr 1fr;gap:8px}.side-panel>.panel-top{display:none}.weapon-card{min-height:156px;padding:10px}.weapon-art{inset:22px 0 46px}.weapon-info{margin-top:58px}.weapon-type{font-size:6px}.weapon-info h2{font-size:19px}.weapon-info p{font-size:7px}.weapon-stats{right:9px;bottom:10px;font-size:6px;gap:5px}.weapon-stats b{font-size:7px}.stat-bars{gap:2px}.stat-bars i{width:7px}.controls-card{padding:10px}.controls-card .panel-top{font-size:7px}.guide-tag{font-size:6px}.control-row{padding:7px 0;gap:6px}.key-group,.key-single{width:39px}.control-row>div:last-child b{font-size:7px}.control-row>div:last-child span{font-size:6px}.key-group kbd{min-width:12px;height:11px;font-size:6px}.key-single kbd{height:14px;font-size:5px;padding:0 3px}.focus-card{grid-column:1/-1;padding:8px}.focus-card p br{display:none}footer{height:31px;font-size:6px;letter-spacing:.7px}.mobile-controls{display:flex;position:fixed;z-index:10;bottom:max(12px,env(safe-area-inset-bottom));left:0;right:0;padding:0 16px;justify-content:space-between;align-items:flex-end;pointer-events:none}.mobile-controls button{pointer-events:auto;color:#f7f3e8;background:#111521d9;border:1px solid #e5c27b66;box-shadow:0 3px 12px #0008;touch-action:none}.dpad{display:flex;flex-direction:column;align-items:center;gap:4px}.dpad>div{display:flex;gap:4px}.dpad button{width:37px;height:35px;border-radius:8px;font-size:13px}.action-pad{display:grid;grid-template-columns:48px 58px;grid-template-rows:49px 35px;align-items:center;gap:4px}.action-pad button{border-radius:50%;font:800 8px var(--body);letter-spacing:.5px}.touch-slash{width:53px;height:53px;background:linear-gradient(145deg,#aa4c50,#652b3c)!important;border-color:#ffc179aa!important;font-size:9px!important}.touch-dash{width:42px;height:42px}.touch-special{grid-column:2;width:37px;height:34px;border-radius:9px!important;color:#ffd17d!important;font-size:17px!important}.side-panel{margin-bottom:104px}.game-shell{padding-bottom:0}}
@media(max-width:390px){.season{display:none}.game-layout{padding-top:8px}.player-readout{width:84px}.wave-readout{gap:3px}.overlay h1{font-size:44px}.weapon-info h2{font-size:17px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 1000, H = 600;
  const $ = id => document.getElementById(id);
  const ui = { start: $('startOverlay'), end: $('endOverlay'), pause: $('pauseBadge'), health: $('healthFill'), healthText: $('healthText'), wave: $('waveText'), count: $('enemyCount'), score: $('scoreText'), best: $('bestScore'), combo: $('comboText'), focus: $('focusFill'), notice: $('centerNotice') };
  const keys = new Set(), held = new Set();
  const tips = ['Perfect timing turns a parry into a counter.', 'A quickstep makes you untouchable for a heartbeat.', 'Build your focus, then let the whirlwind fly.', 'Keep moving. A still target is a dead target.', 'Strike just as their guard breaks for a critical hit.'];
  let state = 'title', last = 0, time = 0, score = 0, best = Number(localStorage.getItem('bladebound-best') || 0), wave = 1, combo = 0, comboTimer = 0, focus = 0, player, enemies = [], particles = [], slashes = [], floaters = [], stars = [], shake = 0, roundTimer = 0, audioCtx = null, soundOn = true, noticeTimer = 0, totalKills = 0;
  ui.best.textContent = pad(best);
  for (let i=0;i<100;i++) stars.push({x:Math.random()*W,y:Math.random()*H*.67,r:Math.random()*1.5+.25,a:Math.random()*.55+.12,p:Math.random()*7});
  function pad(n){return String(Math.floor(n)).padStart(5,'0')}
  function newPlayer(){return {x:W/2,y:H*.57,vx:0,vy:0,r:17,hp:100,max:100,angle:-Math.PI/2,attack:0,attackDone:false,dash:0,dashCd:0,invuln:0,hurt:0,walk:0,glow:0}}
  function beep(freq=250,dur=.08,type='triangle',vol=.035){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch{}}
  function notice(text,duration=1){ui.notice.textContent=text;ui.notice.classList.add('show');noticeTimer=duration}
  function spawnWave(){
    const count=Math.min(3+Math.floor((wave-1)*.72),9);
    enemies=[];
    if(wave%4===0){enemies.push(makeEnemy('boss'));for(let i=0;i<Math.max(1,count-2);i++)enemies.push(makeEnemy(i%3===0?'brute':'runner'))}
    else for(let i=0;i<count;i++)enemies.push(makeEnemy(wave>2&&i%4===3?'brute':i%3===2?'runner':'duelist'));
    ui.wave.textContent=String(wave).padStart(2,'0');updateHUD();
  }
  function makeEnemy(kind){const a=Math.random()*Math.PI*2,r=270+Math.random()*30;const boss=kind==='boss',brute=kind==='brute',runner=kind==='runner';return {x:W/2+Math.cos(a)*r,y:H*.56+Math.sin(a)*r*.58,kind,r:boss?28:brute?20:runner?14:16,hp:boss?10+wave*2:brute?3:runner?1:2,max:boss?10+wave*2:brute?3:runner?1:2,speed:boss?42:brute?48:runner?82:59,angle:0,phase:Math.random()*1.5,mode:'approach',timer:Math.random()*.8,attackCd:.3+Math.random()*1.6,hit:0,dead:false,walk:Math.random()*5,bob:Math.random()*6}}
  function startGame(){state='play';ui.start.classList.add('hidden');ui.end.classList.add('hidden');ui.pause.classList.add('hidden');score=0;wave=1;combo=0;focus=0;totalKills=0;player=newPlayer();particles=[];slashes=[];floaters=[];spawnWave();notice('ROUND ONE',1.25);last=performance.now();beep(440,.13,'sine',.04)}
  function gameOver(){state='dead';ui.end.classList.remove('hidden');ui.pause.classList.add('hidden');$('endTitle').innerHTML='FALLEN,<br><em>NOT FORGOTTEN.</em>'; $('endCopy').textContent=`You survived ${wave} round${wave===1?'':'s'} and took ${totalKills} names.`;$('finalScore').textContent=pad(score);beep(120,.6,'sawtooth',.045);if(score>best){best=score;localStorage.setItem('bladebound-best',best);ui.best.textContent=pad(best);$('endTitle').innerHTML='A LEGEND,<br><em>REMAINS.</em>';}}
  function togglePause(){if(state==='play'){state='paused';ui.pause.classList.remove('hidden')}else if(state==='paused'){state='play';ui.pause.classList.add('hidden');last=performance.now()}}
  function setAction(action){if(state!=='play')return;if(action==='slash')slash();if(action==='dash')dash();if(action==='special')special()}
  function slash(){if(player.attack>0||player.dash>0)return;player.attack=.34;player.attackDone=false;player.glow=.22;beep(200+Math.random()*50,.1,'sawtooth',.025)}
  function dash(){if(player.dashCd>0)return;let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(!dx&&!dy){dx=Math.cos(player.angle);dy=Math.sin(player.angle)}const l=Math.hypot(dx,dy)||1;player.vx=dx/l*510;player.vy=dy/l*510;player.dash=.19;player.dashCd=.8;player.invuln=.3;addBurst(player.x,player.y,'#9eeeff',13,125);beep(580,.12,'sine',.025)}
  function special(){if(focus<100){notice('FOCUS NOT READY',.75);beep(120,.12,'square',.018);return}focus=0;player.attack=0;player.invuln=.75;shake=13;slashes.push({x:player.x,y:player.y,r:12,max:220,life:.52,color:'#ffe08c',wide:true});addBurst(player.x,player.y,'#ffcb71',48,245);beep(90,.32,'sawtooth',.05);for(const e of enemies){if(e.dead)continue;const d=Math.hypot(e.x-player.x,e.y-player.y);if(d<215){damageEnemy(e,e.hp,player.angle,true)}}notice('WHIRLWIND!',1)}
  function updateHUD(){ui.health.style.width=`${Math.max(0,player.hp)}%`;ui.healthText.textContent=Math.max(0,Math.ceil(player.hp));ui.count.textContent=String(enemies.filter(e=>!e.dead).length).padStart(2,'0');ui.score.textContent=pad(score);ui.combo.textContent=combo>1?`${combo}× COMBO`:'—';ui.focus.style.width=`${focus}%`}
  function nearest(){let found=null,dist=Infinity;for(const e of enemies){if(e.dead)continue;const d=Math.hypot(e.x-player.x,e.y-player.y);if(d<dist){dist=d;found=e}}return found}
  function damageEnemy(e,amount,angle,heavy=false){if(e.dead)return;e.hp-=amount;e.hit=.16;const col=e.kind==='boss'?'#ff8b89':e.kind==='runner'?'#8cf2e7':'#ffc36d';for(let i=0;i<(heavy?12:5);i++)particles.push({x:e.x,y:e.y,vx:Math.cos(angle+(Math.random()-.5)*1.3)*(60+Math.random()*180),vy:Math.sin(angle+(Math.random()-.5)*1.3)*(60+Math.random()*180),life:.22+Math.random()*.3,max:.5,size:2+Math.random()*3,color:col});floaters.push({x:e.x,y:e.y-22,text:heavy?'✦':amount>=3?'CRIT!':'-'+amount,life:.65,color:heavy?'#ffe39d':amount>=3?'#ffe39d':'#fff'});shake=Math.max(shake,heavy?10:4);if(e.hp<=0){e.dead=true;totalKills++;score+=(e.kind==='boss'?500:e.kind==='brute'?180:100)+Math.max(0,combo-1)*5;combo++;comboTimer=2.1;focus=Math.min(100,focus+(e.kind==='boss'?24:13));addBurst(e.x,e.y,col,e.kind==='boss'?26:14,180);beep(e.kind==='boss'?120:310,.11,'triangle',.03)}else{score+=10;focus=Math.min(100,focus+(heavy?7:4));beep(155,.07,'square',.019)}updateHUD()}
  function addBurst(x,y,color,n,speed){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=Math.random()*speed;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.55,max:.8,size:1.5+Math.random()*3,color})}}
  function attackHit(){const target=nearest();if(target)player.angle=Math.atan2(target.y-player.y,target.x-player.x);slashes.push({x:player.x,y:player.y,angle:player.angle,r:25,max:105,life:.2,color:'#ffdb9a',wide:false});let hit=0;for(const e of enemies){if(e.dead)continue;const dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),a=Math.atan2(dy,dx),delta=Math.atan2(Math.sin(a-player.angle),Math.cos(a-player.angle));if(d< (e.kind==='boss'?132:116)+e.r&&Math.abs(delta)<(e.kind==='boss'?.96:1.03)){const critical=e.mode==='windup'&&d<95;damageEnemy(e,critical?3:1,player.angle);if(critical){score+=35;floaters.push({x:e.x,y:e.y-39,text:'PARRY!',life:.8,color:'#aef5ee'});focus=Math.min(100,focus+10)}hit++}}
    if(hit){comboTimer=2.1;combo=Math.max(1,combo);if(hit>1){score+=hit*15;notice(`${hit}× CLEAN HIT`,.55)}updateHUD()}}
  function update(dt){time+=dt;if(noticeTimer>0){noticeTimer-=dt;if(noticeTimer<=0)ui.notice.classList.remove('show')}if(shake>0)shake=Math.max(0,shake-dt*28);
    for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.06,dt);p.vy*=Math.pow(.06,dt);p.life-=dt;if(p.life<=0)particles.splice(i,1)}
    for(let i=slashes.length-1;i>=0;i--){slashes[i].life-=dt;slashes[i].r+=(slashes[i].max-slashes[i].r)*dt*13;if(slashes[i].life<=0)slashes.splice(i,1)}
    for(let i=floaters.length-1;i>=0;i--){floaters[i].y-=28*dt;floaters[i].life-=dt;if(floaters[i].life<=0)floaters.splice(i,1)}
    if(state!=='play')return;
    if(comboTimer>0){comboTimer-=dt;if(comboTimer<=0){combo=0;updateHUD()}}
    const p=player;p.invuln=Math.max(0,p.invuln-dt);p.dashCd=Math.max(0,p.dashCd-dt);p.hurt=Math.max(0,p.hurt-dt);p.glow=Math.max(0,p.glow-dt);p.attack=Math.max(0,p.attack-dt);p.dash=Math.max(0,p.dash-dt);
    let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);if(dx||dy){const l=Math.hypot(dx,dy);dx/=l;dy/=l;if(p.dash<=0){p.vx+=(dx*205-p.vx)*Math.min(1,dt*12);p.vy+=(dy*205-p.vy)*Math.min(1,dt*12)}p.walk+=dt*11;if(!nearest())p.angle=Math.atan2(dy,dx)}else if(p.dash<=0){p.vx*=Math.pow(.0008,dt);p.vy*=Math.pow(.0008,dt)}
    p.x+=p.vx*dt;p.y+=p.vy*dt;p.x=Math.max(95,Math.min(W-95,p.x));p.y=Math.max(170,Math.min(H-68,p.y));const target=nearest();if(target&&p.attack<=0&&p.dash<=0&&(!dx&&!dy))p.angle=Math.atan2(target.y-p.y,target.x-p.x);
    if(p.attack>0&&!p.attackDone&&p.attack<.22){p.attackDone=true;attackHit()}
    for(const e of enemies){if(e.dead)continue;e.hit=Math.max(0,e.hit-dt);e.walk+=dt*(e.kind==='runner'?11:7);e.attackCd-=dt;const ax=p.x-e.x,ay=p.y-e.y,d=Math.hypot(ax,ay)||1;e.angle=Math.atan2(ay,ax);if(e.mode==='windup'){e.timer-=dt;if(e.timer<=0){e.mode='swing';e.timer=.2;if(d<e.r+p.r+31&&p.invuln<=0){p.hp-=e.kind==='boss'?19:e.kind==='brute'?16:11;p.hurt=.32;p.invuln=.5;combo=0;comboTimer=0;shake=9;addBurst(p.x,p.y,'#ff6772',14,160);floaters.push({x:p.x,y:p.y-25,text:'-'+(e.kind==='boss'?19:e.kind==='brute'?16:11),life:.75,color:'#ff828c'});beep(100,.22,'sawtooth',.04);updateHUD();if(p.hp<=0){gameOver();return}}}}
      else if(e.mode==='swing'){e.timer-=dt;if(e.timer<=0){e.mode='approach';e.attackCd=1.3+Math.random()*1.3}}
      else if(d>e.r+p.r+34){let speed=e.speed*(d<110?.55:1);e.x+=ax/d*speed*dt;e.y+=ay/d*speed*dt}
      else if(e.attackCd<=0){e.mode='windup';e.timer=e.kind==='runner'?.38:.62;e.attackCd=2.2+Math.random()*1.1}
      const arena=Math.hypot((e.x-W/2)/1,(e.y-H*.55)/.76),bound=315-e.r;if(arena>bound){e.x+=(W/2-e.x)*dt*.6;e.y+=(H*.55-e.y)*dt*.6}}
    if(enemies.every(e=>e.dead)){roundTimer+=dt;if(roundTimer===dt)notice(wave%4===0?'CHAMPION DOWN':'ROUND CLEAR',1.1);if(roundTimer>1.8){roundTimer=0;wave++;p.hp=Math.min(p.max,p.hp+Math.min(13,5+wave));score+=100+wave*20;spawnWave();notice(wave%4===0?'BOSS INBOUND':`ROUND ${String(wave).padStart(2,'0')}`,1.1);updateHUD()}}else roundTimer=0;
  }
  function roundedRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
  function drawFloor(){const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#151826');bg.addColorStop(.52,'#1b1b29');bg.addColorStop(1,'#10131f');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    for(const s of stars){ctx.globalAlpha=s.a*(.7+.3*Math.sin(time*1.6+s.p));ctx.fillStyle='#ffdfad';ctx.fillRect(s.x,s.y,s.r,s.r)}ctx.globalAlpha=1;
    const glow=ctx.createRadialGradient(W/2,H*.56,15,W/2,H*.56,380);glow.addColorStop(0,'#a04e4920');glow.addColorStop(.7,'#562d3519');glow.addColorStop(1,'#10131f00');ctx.fillStyle=glow;ctx.fillRect(0,120,W,H-120);
    // Arena floor perspective and engraved rings
    ctx.save();ctx.translate(W/2,H*.55);ctx.scale(1,.57);for(let r=78;r<=375;r+=44){ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.strokeStyle=r===254?'#df9f653a':'#d6b17c13';ctx.lineWidth=r===254?2:1;ctx.stroke()}ctx.setLineDash([4,13]);ctx.beginPath();ctx.arc(0,0,299,0,Math.PI*2);ctx.strokeStyle='#ffcc7833';ctx.stroke();ctx.setLineDash([]);
    for(let i=0;i<12;i++){const a=i*Math.PI/6+time*.025;const x=Math.cos(a)*254,y=Math.sin(a)*254;ctx.save();ctx.translate(x,y);ctx.rotate(a);ctx.fillStyle=i%3===0?'#e4ad7135':'#e4ad7118';ctx.fillRect(-10,-2,20,4);ctx.restore()}
    ctx.restore();
    const edge=ctx.createRadialGradient(W/2,H*.5,210,W/2,H*.5,590);edge.addColorStop(0,'#00000000');edge.addColorStop(1,'#050710d9');ctx.fillStyle=edge;ctx.fillRect(0,0,W,H);
    // distant lantern glints
    for(let i=0;i<8;i++){const x=90+i*118,y=124+Math.sin(i*1.7)*25;ctx.globalAlpha=.16+.09*Math.sin(time*2+i);ctx.fillStyle=i%2?'#ff7b5f':'#ffd77f';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=15;ctx.beginPath();ctx.arc(x,y,2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}ctx.globalAlpha=1;
  }
  function drawFighter(o,isPlayer=false){const {x,y,r}=o;const boss=o.kind==='boss',runner=o.kind==='runner',brute=o.kind==='brute';const bob=Math.sin(o.walk||0)*1.8;ctx.save();ctx.translate(x,y);
    // ground shadow
    ctx.fillStyle='#03040a88';ctx.beginPath();ctx.ellipse(2,12+bob,r*1.35,r*.55,0,0,Math.PI*2);ctx.fill();
    if(isPlayer&&o.invuln>0){ctx.strokeStyle=`rgba(119,229,255,${.35+.3*Math.sin(time*45)})`;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,27,0,Math.PI*2);ctx.stroke()}
    if(boss){ctx.fillStyle='#562b42';ctx.beginPath();ctx.ellipse(0,0,r*1.2,r*1.34,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ed6a70';ctx.fillRect(-17,-18,9,4);ctx.fillRect(8,-18,9,4);ctx.strokeStyle='#ffb767';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-20,-23);ctx.lineTo(-27,-36);ctx.lineTo(-11,-28);ctx.moveTo(20,-23);ctx.lineTo(27,-36);ctx.lineTo(11,-28);ctx.stroke()}
    else {let bodyColor=isPlayer?'#d9b685':runner?'#438f91':brute?'#87584f':'#79545c';let cape=isPlayer?'#3c3440':runner?'#254b54':brute?'#4c343c':'#422f3c';ctx.fillStyle=cape;ctx.beginPath();ctx.moveTo(-r*.8,-2);ctx.lineTo(-r*1.15,15+bob);ctx.lineTo(r*.7,15+bob);ctx.lineTo(r*.68,-5);ctx.closePath();ctx.fill();ctx.fillStyle=bodyColor;ctx.beginPath();ctx.ellipse(0,0,r*.75,r*.9,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=isPlayer?'#f0d7b4':'#c6a594';ctx.beginPath();ctx.arc(0,-r*.55,r*.54,0,Math.PI*2);ctx.fill();ctx.fillStyle=isPlayer?'#1d2330':runner?'#aaf4e5':'#ffb1a0';ctx.fillRect(2,-r*.62,5,2);ctx.fillStyle=isPlayer?'#b87950':'#a95f63';ctx.fillRect(-r*.6,-2,r*1.2,4)}
    if(o.hit>0){ctx.globalAlpha=Math.min(.8,o.hit*5);ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(0,-4,r*.9,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
    const ang=isPlayer?o.angle:o.angle;ctx.rotate(ang);
    if(isPlayer){let swing=o.attack>0?Math.sin((.34-o.attack)/.34*Math.PI):0;ctx.save();ctx.rotate(-.8+swing*1.55);ctx.strokeStyle='#c69168';ctx.lineWidth=5;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(7,5);ctx.lineTo(26,5);ctx.stroke();ctx.strokeStyle='#e7e5d9';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(24,5);ctx.lineTo(61,5);ctx.stroke();ctx.strokeStyle='#fff5d8';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(27,3);ctx.lineTo(56,3);ctx.stroke();ctx.strokeStyle='#f0bd73';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(24,-1);ctx.lineTo(24,11);ctx.stroke();if(o.attack>0&&o.attack<.31){ctx.globalAlpha=Math.min(1,(.34-o.attack)*5);ctx.strokeStyle='#ffe2a5';ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,67,-.85,.85);ctx.stroke()}ctx.restore();}
    else {ctx.strokeStyle=boss?'#f47b73':brute?'#cb795f':'#9da7a3';ctx.lineWidth=boss?5:3;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(r*.5,5);ctx.lineTo(r+10,5);ctx.stroke();ctx.strokeStyle='#e9ddd0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(r+10,5);ctx.lineTo(r+27,5);ctx.stroke();if(o.mode==='windup'){ctx.globalAlpha=.55+.3*Math.sin(time*28);ctx.strokeStyle='#ff606c';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,r+11,-.65,.65);ctx.stroke();ctx.globalAlpha=1;ctx.fillStyle='#ff8580';ctx.beginPath();ctx.arc(0,-r-15,3+Math.sin(time*25),0,Math.PI*2);ctx.fill()}}
    ctx.restore();
    if(!isPlayer&&(o.hp<o.max||boss)){const w=boss?55:33,yy=y-r-16;ctx.fillStyle='#17121bbf';roundedRect(x-w/2,yy,w,4,2);ctx.fillStyle=boss?'#ff7775':'#f0b879';roundedRect(x-w/2,yy,w*Math.max(0,o.hp/o.max),4,2)}
  }
  function draw(){drawFloor();ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);for(const e of enemies)if(!e.dead)drawFighter(e);if(player)drawFighter(player,true);
    for(const s of slashes){ctx.globalAlpha=Math.max(0,s.life/(s.wide?.52:.2))*.75;ctx.strokeStyle=s.color;ctx.lineWidth=s.wide?8:5;ctx.beginPath();if(s.wide)ctx.arc(s.x,s.y,s.r,0,Math.PI*2);else ctx.arc(s.x,s.y,s.r,s.angle-.85,s.angle+.85);ctx.stroke();ctx.globalAlpha=1}
    for(const p of particles){ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=8;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill()}ctx.shadowBlur=0;ctx.globalAlpha=1;
    for(const f of floaters){ctx.globalAlpha=Math.min(1,f.life*2);ctx.fillStyle=f.color;ctx.textAlign='center';ctx.font='800 16px Barlow Condensed, sans-serif';ctx.shadowColor='#080a10';ctx.shadowBlur=8;ctx.fillText(f.text,f.x,f.y);ctx.shadowBlur=0}ctx.globalAlpha=1;ctx.restore();
    if(state==='title'){ctx.fillStyle='#080a1220';ctx.fillRect(0,0,W,H)}
  }
  function frame(now){const dt=Math.min(.033,(now-last)/1000||0);last=now;if(state!=='paused')update(dt);draw();requestAnimationFrame(frame)}
  function keyDown(e){const key=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();if(key==='escape'||key==='p'){togglePause();return}if(state==='title'&&(key==='enter'||key===' ')){startGame();return}if(state==='dead'&&(key==='enter'||key===' ')){startGame();return}keys.add(key);if(!held.has(key)){held.add(key);if(key===' ')setAction('slash');if(key==='shift')setAction('dash');if(key==='q')setAction('special')}}
  function keyUp(e){const k=e.key.toLowerCase();keys.delete(k);held.delete(k)}
  window.addEventListener('keydown',keyDown);window.addEventListener('keyup',keyUp);window.addEventListener('blur',()=>{keys.clear();held.clear();if(state==='play')togglePause()});
  $('startButton').addEventListener('click',startGame);$('againButton').addEventListener('click',startGame);$('pauseButton').addEventListener('click',togglePause);$('soundToggle').addEventListener('click',()=>{soundOn=!soundOn;$('soundLabel').textContent=soundOn?'SOUND ON':'SOUND OFF';$('soundIcon').textContent=soundOn?'♫':'♪';if(soundOn)beep(440,.08)});
  document.querySelectorAll('.mobile-controls button').forEach(button=>{const direction=button.dataset.key,action=button.dataset.action;const down=e=>{e.preventDefault();if(direction){const key={up:'w',down:'s',left:'a',right:'d'}[direction];keys.add(key);button.setPointerCapture?.(e.pointerId)}else setAction(action)};const up=e=>{e.preventDefault();if(direction)keys.delete({up:'w',down:'s',left:'a',right:'d'}[direction])};button.addEventListener('pointerdown',down);button.addEventListener('pointerup',up);button.addEventListener('pointercancel',up);button.addEventListener('lostpointercapture',up)});
  $('tipText').textContent=tips[Math.floor(Math.random()*tips.length)];
  player=newPlayer();spawnWave();state='title';last=performance.now();requestAnimationFrame(frame);
})();

